// Count FlowFields: SETFILTER on a FlowField) and the kind of its values.
func (t *IssuedReminderHeader) FlowFieldFilterKind(field string) (flowfilter.Kind, bool) {
	switch strings.ToLower(field) {
	case "remaining_amount":
		return flowfilter.KindDecimal, true
	case "interest_amount":
		return flowfilter.KindDecimal, true
	case "additional_fee":
		return flowfilter.KindDecimal, true
	case "tax_amount":
		return flowfilter.KindDecimal, true
	}
	return "", false
}

// flowFieldExpr is the SQL expression computing FlowField field for each row of a query
// on this table: a correlated subquery reading the source like CalcFieldsForRecords (the
// SIFT totals of a covering key, else the entries), with the FlowFilters set on t.
func (t *IssuedReminderHeader) flowFieldExpr(field string) (string, []interface{}) {
	outer := "\"" + fmt.Sprintf("%s$%s", t.company, IssuedReminderHeaderTableName) + "\""
	_ = outer
	switch strings.ToLower(field) {
	case "remaining_amount":
		// Source: the SIFT totals table of a key covering the filters, else the entries
		tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName), false
		_ = useSIFT
		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "reminder_no = "+outer+".no")
		where := "1=1"
		if len(whereClauses) > 0 {
			where = strings.Join(whereClauses, " AND ")
		}
		agg := "COALESCE(SUM(remaining_amount), 0)"
		return "(SELECT " + agg + " FROM \"" + tableName + "\" WHERE " + where + ")", args
	case "interest_amount":
		// Source: the SIFT totals table of a key covering the filters, else the entries
		tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName), false
		_ = useSIFT
		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "reminder_no = "+outer+".no")
		whereClauses = append(whereClauses, "type = ?")
		args = append(args, 2)
		where := "1=1"
		if len(whereClauses) > 0 {
			where = strings.Join(whereClauses, " AND ")
		}
		agg := "COALESCE(SUM(amount), 0)"
		return "(SELECT " + agg + " FROM \"" + tableName + "\" WHERE " + where + ")", args
	case "additional_fee":
		// Source: the SIFT totals table of a key covering the filters, else the entries
		tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName), false
		_ = useSIFT
		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "reminder_no = "+outer+".no")
		whereClauses = append(whereClauses, "type = ?")
		args = append(args, 1)
		where := "1=1"
		if len(whereClauses) > 0 {
			where = strings.Join(whereClauses, " AND ")
		}
		agg := "COALESCE(SUM(amount), 0)"
		return "(SELECT " + agg + " FROM \"" + tableName + "\" WHERE " + where + ")", args
	case "tax_amount":
		// Source: the SIFT totals table of a key covering the filters, else the entries
		tableName, useSIFT := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName), false
		_ = useSIFT
		var whereClauses []string
		var args []interface{}
		whereClauses = append(whereClauses, "reminder_no = "+outer+".no")
		where := "1=1"
		if len(whereClauses) > 0 {
			where = strings.Join(whereClauses, " AND ")
		}
		agg := "COALESCE(SUM(tax_amount), 0)"
		return "(SELECT " + agg + " FROM \"" + tableName + "\" WHERE " + where + ")", args
	}
	return "NULL", nil
}

