// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *IssuedReminderHeader) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, IssuedReminderHeaderTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "reminder_level":
			column = "reminder_level"
		case "no_printed":
			column = "no_printed"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Issued_Reminder_Header", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Issued_Reminder_Header.%s: %w", column, err)
		}
		switch column {
		case "reminder_level":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Issued_Reminder_Header.%s: %w", column, err)
			}
			t.Reminder_level = int(f)
		case "no_printed":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Issued_Reminder_Header.%s: %w", column, err)
			}
			t.No_printed = int(f)
		}
	}
	return nil
}

